// === ESTRUCTURA DEL PATRÓN OBSERVER ===

// 1. Interfaz Observer (el contrato)
interface PriceObserver {
  update(stock: string, price: number): void;
}

// 2. Interfaz Subject (gestiona suscripciones)
interface PriceSource {
  subscribe(observer: PriceObserver): void;
  unsubscribe(observer: PriceObserver): void;
  notify(): void;
}

// 3. Subject Concreto (notifica cuando cambia)
class StockMarket implements PriceSource {
  private observers: PriceObserver[] = [];
  private prices: Map<string, number> = new Map();

  subscribe(observer: PriceObserver) {
    this.observers.push(observer);
  }

  unsubscribe(observer: PriceObserver) {
    this.observers = this.observers.filter(o => o !== observer);
  }

  notify() {
    this.observers.forEach(observer => {
      this.prices.forEach((price, stock) => {
        observer.update(stock, price);
      });
    });
  }

  setPrice(stock: string, price: number) {
    this.prices.set(stock, price);
    this.notify();
  }
}

// 4. Observers Concretos
class Logger implements PriceObserver {
  update(stock: string, price: number) {
    console.log(`[LOG] ${stock}: $${price}`);
  }
}

class AlertSystem implements PriceObserver {
  update(stock: string, price: number) {
    if (price > 100) console.log(`[ALERT] ${stock} superó $100!`);
  }
}

// Uso:
const market = new StockMarket();
market.subscribe(new Logger());
market.subscribe(new AlertSystem());
market.setPrice('AAPL', 150); // Ambos observers notificados

