// 1. Interfaz común
interface Observer {
  update(price: number): void;
}

// 2. Subject mantiene lista de observers
class PriceTracker {
  private observers: Observer[] = [];
  private price: number = 0;

  subscribe(obs: Observer) { this.observers.push(obs); }
  unsubscribe(obs: Observer) {
    this.observers = this.observers.filter(o => o !== obs);
  }

  setPrice(price: number) {
    this.price = price;
    this.observers.forEach(obs => obs.update(price));
  }
}

// 3. Observers implementan update()
class Logger implements Observer {
  update(price: number) { console.log(`Price: ${price}`); }
}

class AlertSystem implements Observer {
  update(price: number) {
    if (price > 100) console.log('Price alert!');
  }
}

// Nuevo observer sin modificar el subject
class Analytics implements Observer {
  update(price: number) { /* track metrics */ }
}

